import {act,fireEvent,render,screen,waitFor} from "@testing-library/react";import {afterEach,expect,test,vi} from "vitest";import {QueryClient,QueryClientProvider} from "@tanstack/react-query";import {DataSection} from "./DataSection";import {Combined,Sequential,TicketScreen} from "./TicketScreen";import {createTicketQueries,prepareTicket,startTicket} from "./queries";import {createHttpApi,deferred,type Ticket,type Comment,type History,type TicketApi} from "./resources";const clients:QueryClient[]=[];function client(){const value=new QueryClient({defaultOptions:{queries:{retry:false,gcTime:Infinity}}});clients.push(value);return value;}afterEach(()=>clients.forEach(value=>value.clear()));function fixture(){const ticket=deferred<Ticket>(),comments=deferred<Comment[]>(),history=deferred<History[]>();const api:TicketApi={ticket:vi.fn(()=>ticket.promise),comments:vi.fn(()=>comments.promise),history:vi.fn(()=>history.promise)};return {api,ticket,comments,history,queries:createTicketQueries(api,"user-a")};}async function mount(ui:React.ReactNode,cache:QueryClient){await act(async()=>{render(<QueryClientProvider client={cache}>{ui}</QueryClientProvider>);});}
test("przygotowanie rozpoczyna trzy niezależne odczyty równolegle",async()=>{const f=fixture(),cache=client();const ready=prepareTicket(cache,f.queries,42);expect(f.api.ticket).toHaveBeenCalledTimes(1);expect(f.api.comments).toHaveBeenCalledTimes(1);expect(f.api.history).toHaveBeenCalledTimes(1);f.ticket.resolve({id:42,title:"API"});f.comments.resolve([]);f.history.resolve([]);await ready;});
test("niezależne granice ujawniają nagłówek przed komentarzami i historią",async()=>{const f=fixture(),cache=client();startTicket(cache,f.queries,42);await mount(<TicketScreen queries={f.queries} id={42}/>,cache);expect(screen.getByText("Ładowanie: Komentarze")).toBeInTheDocument();await act(async()=>f.ticket.resolve({id:42,title:"Eksport"}));expect(await screen.findByRole("heading",{name:"#42 Eksport"})).toBeVisible();expect(screen.getByText("Ładowanie: Komentarze")).toBeInTheDocument();await act(async()=>f.comments.resolve([{id:1,text:"Działa"}]));expect(await screen.findByText("Działa")).toBeVisible();expect(screen.getByText("Ładowanie: Historia")).toBeVisible();await act(async()=>f.history.resolve([]));expect(await screen.findByText("Brak historii.")).toBeVisible();});
test("błąd komentarzy jest lokalny, a reset umożliwia ponowny odczyt",async()=>{const f=fixture(),retry=deferred<Comment[]>(),cache=client();vi.mocked(f.api.comments).mockReturnValueOnce(f.comments.promise).mockReturnValueOnce(retry.promise);const log=vi.spyOn(console,"error").mockImplementation(()=>{});try{startTicket(cache,f.queries,42);await mount(<TicketScreen queries={f.queries} id={42}/>,cache);await act(async()=>{f.ticket.resolve({id:42,title:"Pozostaje"});f.history.resolve([]);f.comments.reject(Error("offline"));});expect(await screen.findByRole("alert")).toHaveTextContent("Nie udało się wczytać");expect(screen.getByRole("heading",{name:"#42 Pozostaje"})).toBeVisible();await act(async()=>fireEvent.click(screen.getByRole("button",{name:"Ponów: Komentarze"})));await waitFor(()=>expect(f.api.comments).toHaveBeenCalledTimes(2));await act(async()=>retry.resolve([{id:2,text:"Po retry"}]));expect(await screen.findByText("Po retry")).toBeVisible();expect(f.api.ticket).toHaveBeenCalledTimes(1);}finally{log.mockRestore();}});
test("błąd refresh z istniejącymi danymi nie zastępuje ich granicą",async()=>{const cache=client();const api:TicketApi={ticket:async id=>({id,title:"A"}),comments:vi.fn().mockResolvedValueOnce([{id:1,text:"Znane dane"}]).mockRejectedValueOnce(Error("offline")),history:async()=>[]};const queries=createTicketQueries(api,"a");await prepareTicket(cache,queries,42);await mount(<TicketScreen queries={queries} id={42}/>,cache);await act(async()=>fireEvent.click(screen.getByRole("button",{name:"Odśwież komentarze"})));expect(await screen.findByRole("alert")).toHaveTextContent("Nie odświeżono komentarzy");expect(screen.getByText("Znane dane")).toBeVisible();});
test("sekwencyjne suspense hooki tworzą zależne rozpoczęcie odczytu",async()=>{const f=fixture(),cache=client();await mount(<DataSection label="Całość"><Sequential queries={f.queries} id={42}/></DataSection>,cache);expect(f.api.ticket).toHaveBeenCalledTimes(1);expect(f.api.comments).not.toHaveBeenCalled();await act(async()=>f.ticket.resolve({id:42,title:"A"}));await waitFor(()=>expect(f.api.comments).toHaveBeenCalledTimes(1));await act(async()=>f.comments.resolve([]));expect(await screen.findByText("A: 0")).toBeVisible();});
test("useSuspenseQueries rozpoczyna zapytania jednej granicy równolegle",async()=>{const f=fixture(),cache=client();await mount(<DataSection label="Razem"><Combined queries={f.queries} id={42}/></DataSection>,cache);expect(f.api.ticket).toHaveBeenCalledTimes(1);expect(f.api.history).toHaveBeenCalledTimes(1);await act(async()=>f.ticket.resolve({id:42,title:"Wspólny"}));expect(screen.getByText("Ładowanie: Razem")).toBeVisible();await act(async()=>f.history.resolve([]));expect(await screen.findByRole("heading",{name:"Wspólny"})).toBeVisible();});
test("powtórne przygotowanie tego samego klucza korzysta ze wspólnego cache",async()=>{const f=fixture(),cache=client();const first=prepareTicket(cache,f.queries,42),second=prepareTicket(cache,f.queries,42);expect(f.api.ticket).toHaveBeenCalledTimes(1);f.ticket.resolve({id:42,title:"A"});f.comments.resolve([]);f.history.resolve([]);await Promise.all([first,second]);await prepareTicket(cache,f.queries,42);expect(f.api.comments).toHaveBeenCalledTimes(1);});
test("adapter HTTP kontroluje status, identyfikator i strukturę listy",async()=>{await expect(createHttpApi(async()=>new Response(null,{status:403})).ticket(42)).rejects.toThrow("HTTP 403");await expect(createHttpApi(async()=>Response.json({id:7,title:"Zły"})).ticket(42)).rejects.toThrow("Niepoprawny ticket");await expect(createHttpApi(async()=>Response.json([{id:1,text:"A"},{id:1,text:"B"}])).comments(42)).rejects.toThrow();});

